@startuml

class House {
  + address : string
  + buildingMaterial : string
}

abstract class Basement {
  + size : double
  + name : string
}

class EarthBasement extends Basement {
  + humidityLevel : double
}

class ConcreteBasement extends Basement {
}

class SemiDetachedHouse extends House {
  + hasOwnGarden : boolean
  + numberOfWindows : int
}

class Carport {
  + isDoubleCarport : boolean
  + hasFlatRoof : boolean
}

class Garage {
  + hasAutomaticGarageDoor : boolean
}

class Company {
  + name : string
  + address : string
}

class JobLog {
  + hours : int
  + price : double
}

House "0..1" -- "0..1" Basement
House "1" -- "*" JobLog
Company "1" -- "*" JobLog
SemiDetachedHouse "1" -- "1" Carport
SemiDetachedHouse "1" -- "1" Garage

@enduml

